package com.example.ayaneooverlay

/**
 * Content of the in-app help guide: one topic per feature, in every UI language
 * (en, ru, nl, es, de, fr, it, zh). Generated from a single source so all languages
 * stay in step. English is the fallback.
 */
object HelpContent {
    class Entry(val title: String, val summary: String, val bullets: List<String>)
    class Topic(val id: String, val icon: String, private val entries: Map<String, Entry>) {
        fun entry(language: String): Entry = entries[language] ?: entries.getValue("en")
    }

    val topics: List<Topic> = listOf(
        Topic("home", "star", mapOf(
            "en" to Entry("Home screen & pages", "Four pages: swipe left or right to move between them.", listOf("Page 1 — dashboard: CPU, GPU, fan, battery, memory, storage, display and FPS. Tap a card to open its controls.", "Page 2 — tools: Keyboard, Touchpad, PC keyboard, performance profiles and Controller.", "Page 3 — Favorites, page 4 — Quick settings. The dots at the bottom show where you are.", "FPS is measured every second; in Aurora Live and Pop Gradient a line chart shows drops and recoveries over the last minute.", "CPU and GPU temperatures turn yellow from 65 °C and red from 85 °C.")),
            "ru" to Entry("Главный экран и страницы", "Четыре страницы: листай влево или вправо.", listOf("Страница 1 — панель: CPU, GPU, вентилятор, батарея, память, накопитель, экран и FPS. Нажми на карточку, чтобы открыть её настройки.", "Страница 2 — инструменты: клавиатура, тачпад, PC-клавиатура, профили и контроллер.", "Страница 3 — избранное, страница 4 — быстрые настройки. Точки внизу показывают, где ты находишься.", "FPS замеряется каждую секунду; в темах «Живая аврора» и «Поп-градиент» линейный график показывает просадки и подъёмы за последнюю минуту.", "Температура CPU и GPU становится жёлтой с 65 °C и красной с 85 °C.")),
            "nl" to Entry("Startscherm en pagina's", "Vier pagina's: veeg naar links of rechts.", listOf("Pagina 1 — dashboard: CPU, GPU, ventilator, batterij, geheugen, opslag, scherm en FPS. Tik op een kaart voor de bediening.", "Pagina 2 — hulpmiddelen: toetsenbord, touchpad, pc-toetsenbord, profielen en controller.", "Pagina 3 — favorieten, pagina 4 — snelle instellingen. De stippen onderaan tonen waar je bent.", "FPS wordt elke seconde gemeten; in Levend noorderlicht en Pop-verloop toont een lijngrafiek dalingen en herstel van de laatste minuut.", "CPU- en GPU-temperatuur worden geel vanaf 65 °C en rood vanaf 85 °C.")),
            "es" to Entry("Pantalla principal y páginas", "Cuatro páginas: desliza a izquierda o derecha.", listOf("Página 1 — panel: CPU, GPU, ventilador, batería, memoria, almacenamiento, pantalla y FPS. Toca una tarjeta para ver sus controles.", "Página 2 — herramientas: teclado, panel táctil, teclado de PC, perfiles y mando.", "Página 3 — favoritos, página 4 — ajustes rápidos. Los puntos de abajo indican dónde estás.", "Los FPS se miden cada segundo; en Aurora viva y Pop degradado un gráfico de línea muestra caídas y subidas del último minuto.", "La temperatura de CPU y GPU se pone amarilla desde 65 °C y roja desde 85 °C.")),
            "de" to Entry("Startbildschirm und Seiten", "Vier Seiten: nach links oder rechts wischen.", listOf("Seite 1 — Dashboard: CPU, GPU, Lüfter, Akku, Speicher, Laufwerk, Display und FPS. Tippe auf eine Karte für ihre Steuerung.", "Seite 2 — Werkzeuge: Tastatur, Touchpad, PC-Tastatur, Profile und Controller.", "Seite 3 — Favoriten, Seite 4 — Schnelleinstellungen. Die Punkte unten zeigen die aktuelle Seite.", "FPS werden jede Sekunde gemessen; in Aurora Live und Pop Gradient zeigt ein Liniendiagramm Einbrüche der letzten Minute.", "CPU- und GPU-Temperatur werden ab 65 °C gelb und ab 85 °C rot.")),
            "fr" to Entry("Écran principal et pages", "Quatre pages : balayez à gauche ou à droite.", listOf("Page 1 — tableau : CPU, GPU, ventilateur, batterie, mémoire, stockage, écran et FPS. Touchez une carte pour ses réglages.", "Page 2 — outils : clavier, pavé tactile, clavier PC, profils et manette.", "Page 3 — favoris, page 4 — réglages rapides. Les points en bas indiquent la page.", "Les FPS sont mesurés chaque seconde ; avec Aurora vivante et Pop dégradé, une courbe montre les chutes de la dernière minute.", "La température CPU et GPU passe au jaune dès 65 °C et au rouge dès 85 °C.")),
            "it" to Entry("Schermata principale e pagine", "Quattro pagine: scorri a sinistra o a destra.", listOf("Pagina 1 — pannello: CPU, GPU, ventola, batteria, memoria, archiviazione, display e FPS. Tocca una scheda per i suoi controlli.", "Pagina 2 — strumenti: tastiera, touchpad, tastiera PC, profili e controller.", "Pagina 3 — preferiti, pagina 4 — impostazioni rapide. I punti in basso indicano la pagina.", "Gli FPS sono misurati ogni secondo; con Aurora viva e Pop sfumato un grafico a linea mostra i cali dell'ultimo minuto.", "La temperatura di CPU e GPU diventa gialla da 65 °C e rossa da 85 °C.")),
            "zh" to Entry("主屏幕与页面", "共四页：左右滑动切换。", listOf("第 1 页 — 仪表盘：CPU、GPU、风扇、电池、内存、存储、屏幕和 FPS。点按卡片打开对应设置。", "第 2 页 — 工具：键盘、触控板、电脑键盘、性能配置和手柄。", "第 3 页 — 收藏，第 4 页 — 快捷设置。底部圆点显示当前位置。", "FPS 每秒测量一次；在“极光”和“流行渐变”主题中，折线图显示最近一分钟的掉帧和回升。", "CPU 和 GPU 温度在 65 °C 起变黄，85 °C 起变红。"))
        )),
        Topic("profiles", "profiles", mapOf(
            "en" to Entry("Performance profiles", "Eco, Balanced, Streaming, Gaming and Max.", listOf("Pick a profile on the dashboard. It sets CPU limits per cluster, GPU frequency and the default fan mode.", "Page 2 → Profiles opens the editor: scheduling mode, fan, CPU cluster limits, GPU limit, GPU lock and Turbo.", "Default fans: Eco off, Balanced and Streaming low, Gaming high, Max full speed. “Reset” restores the defaults.", "After a reboot the last profile comes back, together with a fan mode you chose manually.")),
            "ru" to Entry("Профили производительности", "Eco, Balanced, Streaming, Gaming и Max.", listOf("Выбери профиль на главной. Он задаёт пределы CPU по кластерам, частоту GPU и режим вентилятора по умолчанию.", "Страница 2 → «Профили» открывает редактор: режим планирования, вентилятор, пределы кластеров CPU, предел и фиксация GPU, Турбо.", "Вентилятор по умолчанию: Eco — выкл., Balanced и Streaming — низкий, Gaming — высокий, Max — максимум. «Сбросить» возвращает эти значения.", "После перезагрузки возвращается последний профиль вместе с вручную выбранным режимом вентилятора.")),
            "nl" to Entry("Prestatieprofielen", "Eco, Balanced, Streaming, Gaming en Max.", listOf("Kies een profiel op het dashboard. Het stelt CPU-limieten per cluster, GPU-frequentie en de standaardventilator in.", "Pagina 2 → Profielen opent de editor: planning, ventilator, CPU-clusterlimieten, GPU-limiet, GPU-vergrendeling en Turbo.", "Standaard ventilator: Eco uit, Balanced en Streaming laag, Gaming hoog, Max maximaal. “Herstellen” zet dit terug.", "Na een herstart komt het laatste profiel terug, met een handmatig gekozen ventilatormodus.")),
            "es" to Entry("Perfiles de rendimiento", "Eco, Balanced, Streaming, Gaming y Max.", listOf("Elige un perfil en el panel. Fija límites de CPU por grupo, frecuencia de GPU y el modo de ventilador predeterminado.", "Página 2 → Perfiles abre el editor: planificación, ventilador, límites de CPU, límite y bloqueo de GPU y Turbo.", "Ventilador por defecto: Eco apagado, Balanced y Streaming bajo, Gaming alto, Max máximo. “Restablecer” recupera estos valores.", "Tras reiniciar vuelve el último perfil, junto con el modo de ventilador elegido a mano.")),
            "de" to Entry("Leistungsprofile", "Eco, Balanced, Streaming, Gaming und Max.", listOf("Wähle ein Profil im Dashboard. Es setzt CPU-Grenzen pro Cluster, GPU-Takt und den Standard-Lüftermodus.", "Seite 2 → Profile öffnet den Editor: Planungsmodus, Lüfter, CPU-Cluster, GPU-Grenze, GPU-Sperre und Turbo.", "Standard-Lüfter: Eco aus, Balanced und Streaming niedrig, Gaming hoch, Max maximal. „Zurücksetzen“ stellt sie wieder her.", "Nach einem Neustart kehrt das letzte Profil zurück, samt manuell gewähltem Lüftermodus.")),
            "fr" to Entry("Profils de performance", "Eco, Balanced, Streaming, Gaming et Max.", listOf("Choisissez un profil sur le tableau. Il fixe les limites CPU par groupe, la fréquence GPU et le ventilateur par défaut.", "Page 2 → Profils ouvre l'éditeur : planification, ventilateur, limites CPU, limite et verrou GPU, Turbo.", "Ventilateur par défaut : Eco éteint, Balanced et Streaming bas, Gaming haut, Max maximal. « Réinitialiser » les rétablit.", "Après un redémarrage, le dernier profil revient, avec le mode de ventilateur choisi manuellement.")),
            "it" to Entry("Profili prestazioni", "Eco, Balanced, Streaming, Gaming e Max.", listOf("Scegli un profilo nel pannello. Imposta i limiti CPU per cluster, la frequenza GPU e la ventola predefinita.", "Pagina 2 → Profili apre l'editor: pianificazione, ventola, limiti CPU, limite e blocco GPU, Turbo.", "Ventola predefinita: Eco spenta, Balanced e Streaming bassa, Gaming alta, Max massima. “Ripristina” torna a questi valori.", "Dopo il riavvio torna l'ultimo profilo, con la modalità ventola scelta a mano.")),
            "zh" to Entry("性能配置", "Eco、Balanced、Streaming、Gaming 和 Max。", listOf("在仪表盘选择配置。它会设置各 CPU 集群上限、GPU 频率和默认风扇模式。", "第 2 页 →“配置”打开编辑器：调度模式、风扇、CPU 集群上限、GPU 上限与锁定、Turbo。", "默认风扇：Eco 关闭，Balanced 和 Streaming 低速，Gaming 高速，Max 全速。“重置”恢复这些值。", "重启后会恢复上次的配置，以及你手动选择的风扇模式。"))
        )),
        Topic("turbo", "max", mapOf(
            "en" to Entry("Turbo boost", "Keeps CPU and GPU at the top of the profile's limits.", listOf("Turn it on per profile in the profile editor (block “TURBO”). It runs only while that profile is active.", "Uses the performance governor, keeps all cores awake, gives the app on screen fast cores and stops the GPU from napping between frames.", "It is not an overclock: clocks never exceed the hardware maximum. Expect steadier FPS rather than higher peaks.", "Safety: above 92 °C for 20 s Turbo backs off; it returns after 30 s below 80 °C. Original values are restored when it stops.", "Uses more power and heat — pair it with a High or Max fan.")),
            "ru" to Entry("Турбо-буст", "Держит CPU и GPU на верхней границе лимитов профиля.", listOf("Включается для каждого профиля в редакторе (блок «ТУРБО») и работает, только пока этот профиль выбран.", "Регулятор performance, все ядра активны, приложению на экране — быстрые ядра, GPU не засыпает между кадрами.", "Это не разгон: частоты не превышают заводской максимум. Ждать стоит ровного FPS, а не новых пиков.", "Защита: выше 92 °C в течение 20 с Турбо отключается и возвращается после 30 с ниже 80 °C. При выключении исходные значения восстанавливаются.", "Больше расход и нагрев — лучше вместе с вентилятором High или Max.")),
            "nl" to Entry("Turbo-boost", "Houdt CPU en GPU op de bovengrens van het profiel.", listOf("Per profiel aan te zetten in de profieleditor (blok “TURBO”). Werkt alleen zolang dat profiel actief is.", "Performance-governor, alle kernen wakker, snelle kernen voor de app op het scherm en een GPU die niet sluimert tussen frames.", "Geen overklokken: de klok blijft onder het hardwaremaximum. Verwacht stabielere FPS, geen hogere pieken.", "Veiligheid: boven 92 °C gedurende 20 s schakelt Turbo terug; na 30 s onder 80 °C weer aan. Bij stoppen worden de originele waarden hersteld.", "Meer verbruik en warmte — combineer met ventilator Hoog of Max.")),
            "es" to Entry("Turbo", "Mantiene CPU y GPU en el máximo del perfil.", listOf("Actívalo por perfil en el editor (bloque “TURBO”). Solo funciona mientras ese perfil está activo.", "Gobernador performance, todos los núcleos despiertos, núcleos rápidos para la app en pantalla y GPU sin reposo entre fotogramas.", "No es overclock: nunca supera la frecuencia máxima. Espera FPS más estables, no picos mayores.", "Seguridad: por encima de 92 °C durante 20 s se retira; vuelve tras 30 s por debajo de 80 °C. Al parar se restauran los valores originales.", "Más consumo y calor: úsalo con ventilador alto o máximo.")),
            "de" to Entry("Turbo-Boost", "Hält CPU und GPU an der Obergrenze des Profils.", listOf("Pro Profil im Profileditor (Block „TURBO“) einschalten. Läuft nur, solange dieses Profil aktiv ist.", "Performance-Governor, alle Kerne wach, schnelle Kerne für die App im Vordergrund, GPU ohne Pausen zwischen Frames.", "Kein Übertakten: der Takt bleibt unter dem Hardware-Maximum. Erwarte stabilere FPS statt höherer Spitzen.", "Sicherheit: über 92 °C für 20 s zieht sich Turbo zurück und kommt nach 30 s unter 80 °C wieder. Beim Beenden werden die Originalwerte wiederhergestellt.", "Mehr Verbrauch und Wärme — am besten mit Lüfter Hoch oder Max.")),
            "fr" to Entry("Turbo", "Maintient CPU et GPU au maximum du profil.", listOf("À activer par profil dans l'éditeur (bloc « TURBO »). Il ne fonctionne que tant que ce profil est actif.", "Gouverneur performance, tous les cœurs éveillés, cœurs rapides pour l'app à l'écran, GPU sans pause entre les images.", "Ce n'est pas de l'overclocking : la fréquence ne dépasse jamais le maximum. Attendez-vous à des FPS plus stables, pas plus élevés.", "Sécurité : au-dessus de 92 °C pendant 20 s, Turbo se retire ; il revient après 30 s sous 80 °C. Les valeurs d'origine sont restaurées à l'arrêt.", "Plus de consommation et de chaleur : associez-le à un ventilateur haut ou maximal.")),
            "it" to Entry("Turbo", "Mantiene CPU e GPU al massimo del profilo.", listOf("Si attiva per profilo nell'editor (blocco “TURBO”) e funziona solo con quel profilo attivo.", "Governor performance, tutti i core attivi, core veloci per l'app in primo piano, GPU senza pause tra i fotogrammi.", "Non è overclock: la frequenza non supera mai il massimo. Aspettati FPS più stabili, non picchi più alti.", "Sicurezza: sopra 92 °C per 20 s Turbo si ritira; torna dopo 30 s sotto 80 °C. Allo stop i valori originali vengono ripristinati.", "Più consumo e calore: usalo con ventola alta o massima.")),
            "zh" to Entry("Turbo 加速", "让 CPU 和 GPU 保持在配置上限。", listOf("在配置编辑器（“TURBO”区块）中为每个配置单独开启，只在该配置启用时生效。", "使用 performance 调速器，所有核心保持唤醒，前台应用优先使用大核，GPU 帧间不休眠。", "这不是超频：频率不会超过硬件上限。效果是 FPS 更稳定，而不是峰值更高。", "安全：高于 92 °C 持续 20 秒会自动退出，低于 80 °C 持续 30 秒后恢复。停止时会还原原始数值。", "功耗和发热更高——建议配合高速或全速风扇。"))
        )),
        Topic("fan", "fan", mapOf(
            "en" to Entry("Fan & overheat protection", "Fan modes, custom curve and a safety net when the fan is off.", listOf("Tap the fan card to choose Off, Low, High, Max or a custom curve. A profile sets the default; your manual choice wins until you pick another profile.", "Overheat protection (on by default) works only when the fan is off: above 70 °C for 1 min → low, above 82 °C for 1 min → 50 %, above 90 °C for 2 min → 100 %.", "It steps back one level after cooling for a minute (below 65 °C, 80 °C, 90 °C). Short spikes are ignored.", "The fan icon only spins while the fan really turns.")),
            "ru" to Entry("Вентилятор и защита от перегрева", "Режимы, своя кривая и страховка при выключенном вентиляторе.", listOf("Нажми карточку вентилятора: Выкл., Низкий, Высокий, Макс. или своя кривая. Профиль задаёт режим по умолчанию, ручной выбор действует до смены профиля.", "Защита от перегрева (включена по умолчанию) работает только при выключенном вентиляторе: выше 70 °C 1 мин — низкие обороты, выше 82 °C 1 мин — 50 %, выше 90 °C 2 мин — 100 %.", "Возврат на ступень ниже — после минуты остывания (ниже 65 °C, 80 °C, 90 °C). Короткие скачки игнорируются.", "Иконка вентилятора крутится, только когда он действительно вращается.")),
            "nl" to Entry("Ventilator en oververhittingsbeveiliging", "Modi, eigen curve en een vangnet als de ventilator uit staat.", listOf("Tik op de ventilatorkaart: Uit, Laag, Hoog, Max of eigen curve. Een profiel stelt de standaard in; je eigen keuze geldt tot je een ander profiel kiest.", "Beveiliging (standaard aan) werkt alleen met ventilator uit: boven 70 °C 1 min → laag, boven 82 °C 1 min → 50 %, boven 90 °C 2 min → 100 %.", "Na een minuut afkoelen gaat hij een stap terug (onder 65 °C, 80 °C, 90 °C). Korte pieken worden genegeerd.", "Het ventilatoricoon draait alleen als de ventilator echt draait.")),
            "es" to Entry("Ventilador y protección térmica", "Modos, curva propia y una red de seguridad con el ventilador apagado.", listOf("Toca la tarjeta del ventilador: apagado, bajo, alto, máximo o curva propia. El perfil fija el modo por defecto; tu elección manual manda hasta cambiar de perfil.", "La protección (activa por defecto) solo actúa con el ventilador apagado: más de 70 °C 1 min → bajo, más de 82 °C 1 min → 50 %, más de 90 °C 2 min → 100 %.", "Baja un nivel tras un minuto enfriando (por debajo de 65 °C, 80 °C, 90 °C). Ignora picos breves.", "El icono del ventilador solo gira cuando el ventilador gira de verdad.")),
            "de" to Entry("Lüfter und Überhitzungsschutz", "Modi, eigene Kurve und Schutz bei ausgeschaltetem Lüfter.", listOf("Tippe auf die Lüfterkarte: Aus, Niedrig, Hoch, Max oder eigene Kurve. Das Profil setzt den Standard; deine Wahl gilt bis zum nächsten Profilwechsel.", "Der Schutz (standardmäßig an) greift nur bei ausgeschaltetem Lüfter: über 70 °C 1 min → niedrig, über 82 °C 1 min → 50 %, über 90 °C 2 min → 100 %.", "Nach einer Minute Abkühlung geht es eine Stufe zurück (unter 65 °C, 80 °C, 90 °C). Kurze Spitzen werden ignoriert.", "Das Lüftersymbol dreht sich nur, wenn der Lüfter wirklich läuft.")),
            "fr" to Entry("Ventilateur et protection thermique", "Modes, courbe perso et filet de sécurité ventilateur éteint.", listOf("Touchez la carte ventilateur : éteint, bas, haut, max ou courbe perso. Le profil fixe le défaut ; votre choix manuel prime jusqu'au prochain profil.", "La protection (active par défaut) n'agit que ventilateur éteint : plus de 70 °C 1 min → bas, plus de 82 °C 1 min → 50 %, plus de 90 °C 2 min → 100 %.", "Elle redescend d'un cran après une minute de refroidissement (sous 65 °C, 80 °C, 90 °C). Les pics courts sont ignorés.", "L'icône du ventilateur ne tourne que si le ventilateur tourne vraiment.")),
            "it" to Entry("Ventola e protezione termica", "Modalità, curva personale e protezione a ventola spenta.", listOf("Tocca la scheda ventola: spenta, bassa, alta, max o curva personale. Il profilo imposta il default; la scelta manuale vale fino al cambio profilo.", "La protezione (attiva di default) agisce solo a ventola spenta: oltre 70 °C 1 min → bassa, oltre 82 °C 1 min → 50 %, oltre 90 °C 2 min → 100 %.", "Scende di un livello dopo un minuto di raffreddamento (sotto 65 °C, 80 °C, 90 °C). I picchi brevi sono ignorati.", "L'icona della ventola gira solo se la ventola gira davvero.")),
            "zh" to Entry("风扇与过热保护", "风扇模式、自定义曲线，以及风扇关闭时的安全保护。", listOf("点按风扇卡片：关闭、低速、高速、全速或自定义曲线。配置决定默认模式，手动选择在切换配置前一直有效。", "过热保护（默认开启）仅在风扇关闭时生效：高于 70 °C 持续 1 分钟 → 低速，高于 82 °C 持续 1 分钟 → 50%，高于 90 °C 持续 2 分钟 → 100%。", "降温一分钟后降一级（低于 65 °C、80 °C、90 °C）。短暂波动会被忽略。", "风扇图标只在风扇真正转动时旋转。"))
        )),
        Topic("games", "gaming", mapOf(
            "en" to Entry("Game profiles", "Your own settings for each favorite app — up to 20.", listOf("On the Favorites page hold an app → “Set up game profile”: fan, CPU and GPU limits, GPU lock, Turbo, button layout and vibration.", "Starting the app from Favorites applies its profile first. The tile shows “⚙ PROFILE”, and “⚡ ACTIVE” while it runs.", "When the game closes, PocketHub returns to the profile, layout and vibration you had before. Pressing Home keeps the game profile.", "Hold the tile → “Back to normal profile” to return at any time.")),
            "ru" to Entry("Профили игр", "Свои настройки для каждого приложения из избранного — до 20.", listOf("На странице «Избранное» удерживай приложение → «Настроить профиль игры»: вентилятор, пределы CPU и GPU, фиксация GPU, Турбо, раскладка кнопок и вибрация.", "Запуск из избранного сначала включает профиль игры. На плитке видно «⚙ ПРОФИЛЬ», а пока игра запущена — «⚡ АКТИВЕН».", "Когда игра закрывается, PocketHub возвращает прежний профиль, раскладку и вибрацию. Кнопка «Домой» профиль игры не сбрасывает.", "Удерживай плитку → «Вернуть обычный профиль», чтобы вернуться в любой момент.")),
            "nl" to Entry("Gameprofielen", "Eigen instellingen per favoriete app — tot 20.", listOf("Houd op Favorieten een app vast → “Gameprofiel instellen”: ventilator, CPU- en GPU-limieten, GPU-vergrendeling, Turbo, knopindeling en trilling.", "Starten vanuit Favorieten past eerst het profiel toe. De tegel toont “⚙ PROFIEL” en “⚡ ACTIEF” zolang het draait.", "Sluit de game, dan keren profiel, indeling en trilling van daarvoor terug. Met Home blijft het gameprofiel actief.", "Houd de tegel vast → “Terug naar normaal profiel” om op elk moment terug te gaan.")),
            "es" to Entry("Perfiles de juego", "Ajustes propios para cada app favorita — hasta 20.", listOf("En Favoritos mantén pulsada una app → “Configurar perfil del juego”: ventilador, límites de CPU y GPU, bloqueo de GPU, Turbo, distribución de botones y vibración.", "Al abrir la app desde Favoritos se aplica su perfil. El icono muestra “⚙ PERFIL” y “⚡ ACTIVO” mientras se ejecuta.", "Al cerrar el juego, PocketHub vuelve al perfil, la distribución y la vibración anteriores. Pulsar Inicio mantiene el perfil del juego.", "Mantén el icono → “Volver al perfil normal” cuando quieras.")),
            "de" to Entry("Spielprofile", "Eigene Einstellungen pro Favoriten-App — bis zu 20.", listOf("In Favoriten eine App halten → „Spielprofil einrichten“: Lüfter, CPU- und GPU-Grenzen, GPU-Sperre, Turbo, Tastenlayout und Vibration.", "Beim Start aus den Favoriten wird zuerst das Profil angewendet. Die Kachel zeigt „⚙ PROFIL“ und „⚡ AKTIV“, solange es läuft.", "Wird das Spiel beendet, kehren vorheriges Profil, Layout und Vibration zurück. Die Home-Taste behält das Spielprofil.", "Kachel halten → „Zurück zum normalen Profil“, um jederzeit zurückzukehren.")),
            "fr" to Entry("Profils de jeu", "Des réglages propres à chaque app favorite — jusqu'à 20.", listOf("Dans Favoris, maintenez une app → « Configurer le profil du jeu » : ventilateur, limites CPU et GPU, verrou GPU, Turbo, disposition et vibration.", "Lancer l'app depuis Favoris applique d'abord son profil. La tuile affiche « ⚙ PROFIL » puis « ⚡ ACTIF » pendant le jeu.", "À la fermeture du jeu, PocketHub rétablit le profil, la disposition et la vibration d'avant. Le bouton Accueil conserve le profil du jeu.", "Maintenez la tuile → « Revenir au profil normal » à tout moment.")),
            "it" to Entry("Profili di gioco", "Impostazioni dedicate per ogni app preferita — fino a 20.", listOf("In Preferiti tieni premuta un'app → “Configura profilo di gioco”: ventola, limiti CPU e GPU, blocco GPU, Turbo, layout tasti e vibrazione.", "Avviando l'app dai Preferiti si applica prima il suo profilo. La scheda mostra “⚙ PROFILO” e “⚡ ATTIVO” durante il gioco.", "Alla chiusura del gioco PocketHub ripristina profilo, layout e vibrazione precedenti. Il tasto Home mantiene il profilo di gioco.", "Tieni premuta la scheda → “Torna al profilo normale” in qualsiasi momento.")),
            "zh" to Entry("游戏配置", "为每个收藏应用单独设置——最多 20 个。", listOf("在“收藏”页长按应用 →“设置游戏配置”：风扇、CPU 与 GPU 上限、GPU 锁定、Turbo、按键布局和震动。", "从收藏启动应用时会先应用其配置。图标显示“⚙ 配置”，运行时显示“⚡ 已启用”。", "游戏关闭后，PocketHub 恢复之前的配置、按键布局和震动。按主页键不会退出游戏配置。", "长按图标 →“恢复普通配置”可随时返回。"))
        )),
        Topic("favorites", "star", mapOf(
            "en" to Entry("Favorites", "Your apps on page 3, one tap away.", listOf("“+” adds an app from the installed list (with search).", "Tap an icon to open the app on the top screen.", "Hold an icon to open it on the bottom screen, move it left or right, set up a game profile or remove it.")),
            "ru" to Entry("Избранное", "Твои приложения на странице 3 — в одно касание.", listOf("«+» добавляет приложение из списка установленных (с поиском).", "Нажатие на иконку открывает приложение на верхнем экране.", "Удержание: открыть на нижнем экране, сдвинуть влево или вправо, настроить профиль игры или убрать из избранного.")),
            "nl" to Entry("Favorieten", "Je apps op pagina 3, met één tik.", listOf("“+” voegt een app toe uit de lijst met geïnstalleerde apps (met zoeken).", "Tik op een icoon om de app op het bovenste scherm te openen.", "Houd vast om op het onderste scherm te openen, te verplaatsen, een gameprofiel in te stellen of te verwijderen.")),
            "es" to Entry("Favoritos", "Tus apps en la página 3, a un toque.", listOf("“+” añade una app de la lista de instaladas (con búsqueda).", "Toca un icono para abrir la app en la pantalla superior.", "Mantén pulsado para abrirla abajo, moverla, configurar un perfil de juego o quitarla.")),
            "de" to Entry("Favoriten", "Deine Apps auf Seite 3, mit einem Tipp.", listOf("„+“ fügt eine installierte App hinzu (mit Suche).", "Tippe auf ein Symbol, um die App auf dem oberen Bildschirm zu öffnen.", "Halten: unten öffnen, verschieben, Spielprofil einrichten oder entfernen.")),
            "fr" to Entry("Favoris", "Vos apps en page 3, à portée d'un toucher.", listOf("« + » ajoute une app installée (avec recherche).", "Touchez une icône pour ouvrir l'app sur l'écran du haut.", "Maintenez pour l'ouvrir en bas, la déplacer, configurer un profil de jeu ou la retirer.")),
            "it" to Entry("Preferiti", "Le tue app a pagina 3, a portata di tocco.", listOf("“+” aggiunge un'app installata (con ricerca).", "Tocca un'icona per aprire l'app sullo schermo superiore.", "Tieni premuto per aprirla sotto, spostarla, configurare un profilo di gioco o rimuoverla.")),
            "zh" to Entry("收藏", "常用应用放在第 3 页，一点即开。", listOf("“+”可从已安装应用中添加（支持搜索）。", "点按图标在上屏打开应用。", "长按可在下屏打开、左右移动、设置游戏配置或移除。"))
        )),
        Topic("quick", "wifi", mapOf(
            "en" to Entry("Quick settings", "Page 4: switches for system functions.", listOf("Default tiles: Wi-Fi, Bluetooth and Auto-rotate. Tap to switch; active tiles light up.", "“+” adds Airplane mode, Location, Do not disturb, Battery saver, Dark theme and Force landscape.", "Force landscape locks the top screen horizontally, even for apps that want portrait.", "Hold a tile to open its system settings page, move it or remove it.")),
            "ru" to Entry("Быстрые настройки", "Страница 4: переключатели системных функций.", listOf("По умолчанию: Wi-Fi, Bluetooth и Автоповорот. Нажатие переключает, включённые плитки подсвечиваются.", "«+» добавляет режим полёта, местоположение, «Не беспокоить», энергосбережение, тёмную тему и «Альбомная всегда».", "«Альбомная всегда» фиксирует верхний экран горизонтально даже для приложений, которые просят портрет.", "Удержание плитки: открыть системные настройки, сдвинуть или убрать.")),
            "nl" to Entry("Snelle instellingen", "Pagina 4: schakelaars voor systeemfuncties.", listOf("Standaard: wifi, Bluetooth en automatisch draaien. Tik om te schakelen; actieve tegels lichten op.", "“+” voegt vliegtuigmodus, locatie, niet storen, batterijbesparing, donker thema en liggend forceren toe.", "Liggend forceren zet het bovenste scherm vast in liggende stand, ook voor apps die staand willen.", "Houd een tegel vast om de systeeminstelling te openen, te verplaatsen of te verwijderen.")),
            "es" to Entry("Ajustes rápidos", "Página 4: interruptores de funciones del sistema.", listOf("Por defecto: Wi-Fi, Bluetooth y giro automático. Toca para cambiar; los activos se iluminan.", "“+” añade modo avión, ubicación, no molestar, ahorro de batería, tema oscuro y forzar horizontal.", "Forzar horizontal fija la pantalla superior en horizontal, incluso para apps que piden vertical.", "Mantén un acceso para abrir sus ajustes, moverlo o quitarlo.")),
            "de" to Entry("Schnelleinstellungen", "Seite 4: Schalter für Systemfunktionen.", listOf("Standard: WLAN, Bluetooth und automatisches Drehen. Tippen schaltet um; aktive Kacheln leuchten.", "„+“ fügt Flugmodus, Standort, Nicht stören, Energiesparen, dunkles Design und Querformat erzwingen hinzu.", "Querformat erzwingen fixiert den oberen Bildschirm quer, auch für Apps, die Hochformat wollen.", "Kachel halten: Systemeinstellungen öffnen, verschieben oder entfernen.")),
            "fr" to Entry("Réglages rapides", "Page 4 : interrupteurs de fonctions système.", listOf("Par défaut : Wi-Fi, Bluetooth et rotation auto. Touchez pour basculer ; les tuiles actives s'allument.", "« + » ajoute mode avion, localisation, ne pas déranger, économiseur, thème sombre et paysage forcé.", "Paysage forcé bloque l'écran du haut à l'horizontale, même pour les apps en portrait.", "Maintenez une tuile pour ouvrir ses réglages, la déplacer ou la retirer.")),
            "it" to Entry("Impostazioni rapide", "Pagina 4: interruttori delle funzioni di sistema.", listOf("Predefiniti: Wi-Fi, Bluetooth e rotazione automatica. Tocca per cambiare; le schede attive si illuminano.", "“+” aggiunge modalità aereo, posizione, non disturbare, risparmio batteria, tema scuro e orizzontale forzato.", "Orizzontale forzato blocca lo schermo superiore in orizzontale, anche per le app verticali.", "Tieni premuta una scheda per aprirne le impostazioni, spostarla o rimuoverla.")),
            "zh" to Entry("快捷设置", "第 4 页：系统功能开关。", listOf("默认：Wi-Fi、蓝牙和自动旋转。点按切换，开启的图块会高亮。", "“+”可添加飞行模式、定位、勿扰、省电、深色主题和强制横屏。", "强制横屏会将上屏固定为横向，即使应用要求竖屏。", "长按图块可打开系统设置、移动或移除。"))
        )),
        Topic("keyboard", "keyboard", mapOf(
            "en" to Entry("PocketHub Keyboard", "On-screen keyboard on the lower screen.", listOf("Enable and select it in Settings → Keyboard. Choose languages, theme (including Retro keycaps), key size and the utility bar.", "Page 2 → Keyboard opens it anytime, even without a text field: keys are typed into the top screen (needs root).", "Latin letters are typed as keys; Cyrillic, Chinese and emoji are pasted with Ctrl+V and your clipboard is restored.", "The utility bar has clipboard history, emoji, copy, cut and paste. Tap a text field on top to return to normal typing.")),
            "ru" to Entry("Клавиатура PocketHub", "Экранная клавиатура на нижнем экране.", listOf("Включи и выбери её в Настройки → Клавиатура. Там же языки, тема (в том числе «Ретро-клавиши»), размер клавиш и панель кнопок.", "Страница 2 → «Клавиатура» открывает её в любой момент, даже без текстового поля: ввод уходит на верхний экран (нужен root).", "Латиница печатается нажатиями клавиш; кириллица, китайский и эмодзи вставляются через Ctrl+V, буфер обмена потом восстанавливается.", "На панели — история буфера, эмодзи, копировать, вырезать и вставить. Нажми на поле ввода наверху, чтобы вернуться к обычному вводу.")),
            "nl" to Entry("PocketHub-toetsenbord", "Schermtoetsenbord op het onderste scherm.", listOf("Inschakelen en kiezen in Instellingen → Toetsenbord. Daar ook talen, thema (o.a. Retro-toetsen), toetsgrootte en hulpbalk.", "Pagina 2 → Toetsenbord opent het altijd, ook zonder tekstveld: invoer gaat naar het bovenste scherm (root nodig).", "Latijnse letters worden als toetsen getypt; Cyrillisch, Chinees en emoji via Ctrl+V, je klembord wordt hersteld.", "De hulpbalk heeft klembordgeschiedenis, emoji, kopiëren, knippen en plakken. Tik op een tekstveld boven voor normaal typen.")),
            "es" to Entry("Teclado PocketHub", "Teclado en pantalla en la pantalla inferior.", listOf("Actívalo y selecciónalo en Ajustes → Teclado. Allí eliges idiomas, tema (incluido Teclas retro), tamaño y barra de acciones.", "Página 2 → Teclado lo abre en cualquier momento, incluso sin campo de texto: escribe en la pantalla superior (requiere root).", "Las letras latinas se envían como teclas; cirílico, chino y emoji se pegan con Ctrl+V y se restaura tu portapapeles.", "La barra incluye historial del portapapeles, emoji, copiar, cortar y pegar. Toca un campo de texto arriba para volver al modo normal.")),
            "de" to Entry("PocketHub-Tastatur", "Bildschirmtastatur auf dem unteren Bildschirm.", listOf("In Einstellungen → Tastatur aktivieren und auswählen. Dort auch Sprachen, Design (inkl. Retro-Tasten), Tastengröße und Werkzeugleiste.", "Seite 2 → Tastatur öffnet sie jederzeit, auch ohne Textfeld: Eingaben gehen auf den oberen Bildschirm (Root nötig).", "Lateinische Buchstaben werden als Tasten gesendet; Kyrillisch, Chinesisch und Emoji per Strg+V, die Zwischenablage wird wiederhergestellt.", "Die Leiste bietet Zwischenablage-Verlauf, Emoji, Kopieren, Ausschneiden und Einfügen. Tippe oben auf ein Textfeld für normales Tippen.")),
            "fr" to Entry("Clavier PocketHub", "Clavier à l'écran sur l'écran du bas.", listOf("Activez-le et choisissez-le dans Réglages → Clavier : langues, thème (dont Touches rétro), taille des touches et barre d'outils.", "Page 2 → Clavier l'ouvre à tout moment, même sans champ de texte : la saisie va à l'écran du haut (root requis).", "Les lettres latines sont envoyées comme touches ; cyrillique, chinois et emoji sont collés via Ctrl+V, le presse-papiers est restauré.", "La barre offre historique du presse-papiers, emoji, copier, couper et coller. Touchez un champ en haut pour revenir à la saisie normale.")),
            "it" to Entry("Tastiera PocketHub", "Tastiera su schermo nello schermo inferiore.", listOf("Attivala e sceglila in Impostazioni → Tastiera: lingue, tema (anche Tasti retro), dimensione tasti e barra strumenti.", "Pagina 2 → Tastiera la apre sempre, anche senza campo di testo: scrive sullo schermo superiore (serve root).", "Le lettere latine sono inviate come tasti; cirillico, cinese ed emoji vengono incollati con Ctrl+V e gli appunti ripristinati.", "La barra offre cronologia appunti, emoji, copia, taglia e incolla. Tocca un campo di testo in alto per la digitazione normale.")),
            "zh" to Entry("PocketHub 键盘", "显示在下屏的屏幕键盘。", listOf("在 设置 → 键盘 中启用并选择。可设置语言、主题（含“复古键帽”）、按键大小和工具栏。", "第 2 页 →“键盘”可随时打开，即使没有输入框：输入发送到上屏（需要 root）。", "拉丁字母以按键方式输入；西里尔文、中文和表情通过 Ctrl+V 粘贴，之后恢复剪贴板。", "工具栏提供剪贴板历史、表情、复制、剪切和粘贴。点按上屏输入框即可恢复普通输入。"))
        )),
        Topic("touchpad", "touchpad", mapOf(
            "en" to Entry("Touchpad (mouse)", "A touchpad on the lower screen with a cursor on top.", listOf("One finger moves the cursor; faster strokes travel further.", "Tap = left click, two-finger tap or RIGHT = right click, two fingers up/down = scroll.", "Hold LEFT and move to drag: select text, scroll lists, move sliders. ✕ closes the touchpad.", "Needs root and “display over other apps”.")),
            "ru" to Entry("Тачпад (мышь)", "Тачпад на нижнем экране и курсор на верхнем.", listOf("Один палец двигает курсор; чем быстрее движение, тем дальше он уходит.", "Тап — левый клик, тап двумя пальцами или ПРАВАЯ — правый клик, два пальца вверх-вниз — прокрутка.", "Зажми ЛЕВАЯ и веди — перетаскивание: выделение текста, списки, ползунки. ✕ закрывает тачпад.", "Нужны root и разрешение «поверх других окон».")),
            "nl" to Entry("Touchpad (muis)", "Een touchpad onderaan met een cursor bovenaan.", listOf("Eén vinger beweegt de cursor; snellere bewegingen gaan verder.", "Tik = linkerklik, tik met twee vingers of RECHTS = rechterklik, twee vingers op/neer = scrollen.", "Houd LINKS vast en beweeg om te slepen: tekst selecteren, lijsten, schuifregelaars. ✕ sluit.", "Root en “weergeven over andere apps” nodig.")),
            "es" to Entry("Panel táctil (ratón)", "Un panel táctil abajo con un cursor arriba.", listOf("Un dedo mueve el cursor; los movimientos rápidos llegan más lejos.", "Toque = clic izquierdo, toque con dos dedos o DERECHO = clic derecho, dos dedos arriba/abajo = desplazar.", "Mantén IZQUIERDO y mueve para arrastrar: seleccionar texto, listas, deslizadores. ✕ lo cierra.", "Necesita root y “mostrar sobre otras apps”.")),
            "de" to Entry("Touchpad (Maus)", "Ein Touchpad unten mit Cursor oben.", listOf("Ein Finger bewegt den Cursor; schnelle Bewegungen gehen weiter.", "Tippen = Linksklick, Zwei-Finger-Tipp oder RECHTS = Rechtsklick, zwei Finger hoch/runter = Scrollen.", "LINKS halten und bewegen zum Ziehen: Text markieren, Listen, Regler. ✕ schließt.", "Root und „Über anderen Apps einblenden“ nötig.")),
            "fr" to Entry("Pavé tactile (souris)", "Un pavé tactile en bas, un curseur en haut.", listOf("Un doigt déplace le curseur ; les gestes rapides vont plus loin.", "Toucher = clic gauche, toucher à deux doigts ou DROIT = clic droit, deux doigts haut/bas = défilement.", "Maintenez GAUCHE et bougez pour glisser : sélection de texte, listes, curseurs. ✕ ferme.", "Nécessite root et « affichage par-dessus les autres apps ».")),
            "it" to Entry("Touchpad (mouse)", "Un touchpad in basso con cursore in alto.", listOf("Un dito muove il cursore; i movimenti rapidi vanno più lontano.", "Tocco = clic sinistro, tocco a due dita o DESTRO = clic destro, due dita su/giù = scorrimento.", "Tieni SINISTRO e muovi per trascinare: selezione testo, liste, cursori. ✕ chiude.", "Servono root e “mostra sopra altre app”.")),
            "zh" to Entry("触控板（鼠标）", "下屏为触控板，上屏显示光标。", listOf("单指移动光标；滑动越快移动越远。", "轻点 = 左键，双指轻点或“右键” = 右键，双指上下滑动 = 滚动。", "按住“左键”并移动即可拖动：选择文字、滚动列表、拖动滑块。✕ 关闭触控板。", "需要 root 和“显示在其他应用上层”权限。"))
        )),
        Topic("pckeyboard", "pc", mapOf(
            "en" to Entry("PC keyboard", "Full English computer layout on the lower screen.", listOf("Esc, F1–F12, number row with symbols, Tab, Caps, Enter, Ctrl, Win, Alt, arrows, Home, End, PgUp, PgDn, Ins, PrtSc.", "Modifiers are sticky: tap once for the next key (blue), twice to lock (orange), again to release. Shortcuts like Ctrl+C or Alt+Tab work.", "Backspace, Delete, arrows and page keys repeat while held. Keys go to the top screen (needs root).")),
            "ru" to Entry("PC-клавиатура", "Полная английская раскладка компьютера на нижнем экране.", listOf("Esc, F1–F12, цифры с символами, Tab, Caps, Enter, Ctrl, Win, Alt, стрелки, Home, End, PgUp, PgDn, Ins, PrtSc.", "Модификаторы залипают: одно нажатие — на следующую клавишу (синий), двойное — фиксация (оранжевый), ещё одно — снять. Работают Ctrl+C, Alt+Tab и т. п.", "Backspace, Delete, стрелки и PgUp/PgDn повторяются при удержании. Нажатия уходят на верхний экран (нужен root).")),
            "nl" to Entry("Pc-toetsenbord", "Volledige Engelse pc-indeling op het onderste scherm.", listOf("Esc, F1–F12, cijferrij met symbolen, Tab, Caps, Enter, Ctrl, Win, Alt, pijlen, Home, End, PgUp, PgDn, Ins, PrtSc.", "Modifiers blijven plakken: één tik voor de volgende toets (blauw), twee om te vergrendelen (oranje), nog eens om los te laten. Ctrl+C of Alt+Tab werken.", "Backspace, Delete, pijlen en paginatoetsen herhalen bij vasthouden. Toetsen gaan naar het bovenste scherm (root nodig).")),
            "es" to Entry("Teclado de PC", "Distribución completa de PC en inglés en la pantalla inferior.", listOf("Esc, F1–F12, fila numérica con símbolos, Tab, Caps, Enter, Ctrl, Win, Alt, flechas, Inicio, Fin, RePág, AvPág, Ins, ImprPant.", "Los modificadores se quedan pulsados: un toque para la siguiente tecla (azul), dos para fijar (naranja), otro para soltar. Funcionan Ctrl+C o Alt+Tab.", "Retroceso, Supr, flechas y teclas de página se repiten al mantener. Las teclas van a la pantalla superior (requiere root).")),
            "de" to Entry("PC-Tastatur", "Volles englisches PC-Layout auf dem unteren Bildschirm.", listOf("Esc, F1–F12, Zahlenreihe mit Symbolen, Tab, Caps, Enter, Strg, Win, Alt, Pfeile, Pos1, Ende, Bild↑, Bild↓, Einfg, Druck.", "Modifikatoren rasten ein: einmal tippen für die nächste Taste (blau), zweimal zum Sperren (orange), erneut zum Lösen. Strg+C oder Alt+Tab funktionieren.", "Rücktaste, Entf, Pfeile und Bildtasten wiederholen beim Halten. Eingaben gehen auf den oberen Bildschirm (Root nötig).")),
            "fr" to Entry("Clavier PC", "Disposition PC anglaise complète sur l'écran du bas.", listOf("Échap, F1–F12, rangée de chiffres avec symboles, Tab, Verr. maj, Entrée, Ctrl, Win, Alt, flèches, Début, Fin, PgPréc, PgSuiv, Inser, ImprÉcr.", "Les modificateurs restent enfoncés : un toucher pour la touche suivante (bleu), deux pour verrouiller (orange), encore pour relâcher. Ctrl+C ou Alt+Tab fonctionnent.", "Retour arrière, Suppr, flèches et touches de page se répètent au maintien. Les touches vont à l'écran du haut (root requis).")),
            "it" to Entry("Tastiera PC", "Layout PC inglese completo sullo schermo inferiore.", listOf("Esc, F1–F12, riga numerica con simboli, Tab, Bloc maiusc, Invio, Ctrl, Win, Alt, frecce, Home, Fine, PagSu, PagGiù, Ins, Stamp.", "I modificatori restano attivi: un tocco per il tasto successivo (blu), due per bloccare (arancione), ancora per rilasciare. Funzionano Ctrl+C o Alt+Tab.", "Backspace, Canc, frecce e tasti pagina si ripetono tenendo premuto. I tasti vanno allo schermo superiore (serve root).")),
            "zh" to Entry("电脑键盘", "下屏显示完整的英文电脑布局。", listOf("Esc、F1–F12、带符号的数字行、Tab、Caps、Enter、Ctrl、Win、Alt、方向键、Home、End、PgUp、PgDn、Ins、PrtSc。", "修饰键为粘滞模式：点一次作用于下一个键（蓝色），点两次锁定（橙色），再点取消。支持 Ctrl+C、Alt+Tab 等快捷键。", "退格、删除、方向键和翻页键长按会连发。按键发送到上屏（需要 root）。"))
        )),
        Topic("screens", "display", mapOf(
            "en" to Entry("Screens, focus & touchpad mode", "Choose which screens are on and where input goes.", listOf("Screens: top, bottom or both. Focus Auto follows the last touch; Top or Bottom locks control to one screen.", "The firmware touchpad or cursor mode turns the lower screen into an input pad for the top one.", "If the lower screen is off, the AYANEO button on the console turns it back on.", "The refresh-rate window sets the top screen's refresh rate.")),
            "ru" to Entry("Экраны, фокус и режим тачпада", "Какие экраны включены и куда идёт ввод.", listOf("«Экраны»: верхний, нижний или оба. Фокус Auto следует за последним касанием; Top или Bottom закрепляет управление за экраном.", "Режим тачпада или курсора прошивки превращает нижний экран в панель ввода для верхнего.", "Если нижний экран выключен, кнопка AYANEO на корпусе включает его обратно.", "Окно частоты обновления задаёт частоту верхнего экрана.")),
            "nl" to Entry("Schermen, focus en touchpadmodus", "Welke schermen aan staan en waar invoer heen gaat.", listOf("Schermen: boven, onder of beide. Focus Auto volgt de laatste aanraking; Top of Bottom vergrendelt de bediening.", "De touchpad- of cursormodus van de firmware maakt van het onderste scherm een invoerpaneel voor het bovenste.", "Staat het onderste scherm uit, dan zet de AYANEO-knop het weer aan.", "Het verversingsvenster stelt de verversingssnelheid van het bovenste scherm in.")),
            "es" to Entry("Pantallas, foco y modo táctil", "Qué pantallas están encendidas y a dónde va la entrada.", listOf("Pantallas: superior, inferior o ambas. El foco Auto sigue el último toque; Top o Bottom fija el control.", "El modo panel táctil o cursor del firmware convierte la pantalla inferior en un panel para la superior.", "Si la pantalla inferior está apagada, el botón AYANEO la vuelve a encender.", "La ventana de frecuencia ajusta la tasa de refresco de la pantalla superior.")),
            "de" to Entry("Bildschirme, Fokus und Touchpad-Modus", "Welche Bildschirme an sind und wohin Eingaben gehen.", listOf("Bildschirme: oben, unten oder beide. Fokus Auto folgt der letzten Berührung; Top oder Bottom fixiert die Steuerung.", "Der Touchpad- oder Cursormodus der Firmware macht den unteren Bildschirm zum Eingabefeld für den oberen.", "Ist der untere Bildschirm aus, schaltet ihn die AYANEO-Taste wieder ein.", "Das Bildwiederholraten-Fenster stellt die Rate des oberen Bildschirms ein.")),
            "fr" to Entry("Écrans, focus et mode pavé", "Quels écrans sont allumés et où va la saisie.", listOf("Écrans : haut, bas ou les deux. Le focus Auto suit le dernier toucher ; Top ou Bottom verrouille le contrôle.", "Le mode pavé tactile ou curseur du firmware fait de l'écran du bas un pavé pour celui du haut.", "Si l'écran du bas est éteint, le bouton AYANEO le rallume.", "La fenêtre de fréquence règle le taux de rafraîchissement de l'écran du haut.")),
            "it" to Entry("Schermi, focus e modalità touchpad", "Quali schermi sono accesi e dove va l'input.", listOf("Schermi: superiore, inferiore o entrambi. Il focus Auto segue l'ultimo tocco; Top o Bottom blocca il controllo.", "La modalità touchpad o cursore del firmware trasforma lo schermo inferiore in un pad per quello superiore.", "Se lo schermo inferiore è spento, il tasto AYANEO lo riaccende.", "La finestra della frequenza imposta il refresh dello schermo superiore.")),
            "zh" to Entry("屏幕、焦点与触控板模式", "选择开启哪些屏幕以及输入发往何处。", listOf("屏幕：上屏、下屏或双屏。焦点 Auto 跟随最后一次触摸；Top 或 Bottom 固定控制屏幕。", "固件的触控板或光标模式会把下屏变成上屏的输入板。", "下屏关闭时，按机身上的 AYANEO 键可重新打开。", "刷新率窗口用于设置上屏刷新率。"))
        )),
        Topic("controller", "controller", mapOf(
            "en" to Entry("Controller", "Built-in gamepad: vibration and button layout.", listOf("Page 2 → Controller: vibration off, low, medium or high.", "Button layout: Xbox or Japanese (A/B and X/Y swapped).", "Game profiles can change layout and vibration per game and restore them when the game closes.")),
            "ru" to Entry("Контроллер", "Встроенный геймпад: вибрация и раскладка кнопок.", listOf("Страница 2 → «Контроллер»: вибрация выкл., слабая, средняя или сильная.", "Раскладка кнопок: Xbox или японская (A/B и X/Y меняются местами).", "Профили игр могут менять раскладку и вибрацию для каждой игры и возвращать их после её закрытия.")),
            "nl" to Entry("Controller", "Ingebouwde gamepad: trilling en knopindeling.", listOf("Pagina 2 → Controller: trilling uit, laag, gemiddeld of sterk.", "Knopindeling: Xbox of Japans (A/B en X/Y omgewisseld).", "Gameprofielen kunnen indeling en trilling per game wijzigen en daarna herstellen.")),
            "es" to Entry("Mando", "Mando integrado: vibración y distribución.", listOf("Página 2 → Mando: vibración apagada, baja, media o alta.", "Distribución: Xbox o japonesa (A/B y X/Y intercambiados).", "Los perfiles de juego pueden cambiar distribución y vibración por juego y restaurarlas al cerrarlo.")),
            "de" to Entry("Controller", "Eingebautes Gamepad: Vibration und Tastenlayout.", listOf("Seite 2 → Controller: Vibration aus, niedrig, mittel oder stark.", "Tastenlayout: Xbox oder japanisch (A/B und X/Y vertauscht).", "Spielprofile können Layout und Vibration pro Spiel ändern und danach wiederherstellen.")),
            "fr" to Entry("Manette", "Manette intégrée : vibration et disposition.", listOf("Page 2 → Manette : vibration éteinte, faible, moyenne ou forte.", "Disposition : Xbox ou japonaise (A/B et X/Y inversés).", "Les profils de jeu peuvent changer disposition et vibration par jeu et les rétablir à la fermeture.")),
            "it" to Entry("Controller", "Gamepad integrato: vibrazione e layout tasti.", listOf("Pagina 2 → Controller: vibrazione spenta, bassa, media o alta.", "Layout tasti: Xbox o giapponese (A/B e X/Y invertiti).", "I profili di gioco possono cambiare layout e vibrazione per gioco e ripristinarli alla chiusura.")),
            "zh" to Entry("手柄", "内置手柄：震动与按键布局。", listOf("第 2 页 →“手柄”：震动关闭、弱、中或强。", "按键布局：Xbox 或日式（A/B 与 X/Y 互换）。", "游戏配置可为每个游戏单独设置布局和震动，并在关闭游戏后恢复。"))
        )),
        Topic("media", "brightness", mapOf(
            "en" to Entry("Brightness, sound & screenshots", "Per-screen controls on the dashboard.", listOf("Brightness is set separately for each screen.", "Sound can be set separately for the top and bottom screen (screen audio).", "Capture saves the top, bottom or both screens.")),
            "ru" to Entry("Яркость, звук и снимки", "Настройки по экранам на главной.", listOf("Яркость настраивается отдельно для каждого экрана.", "Звук можно задать отдельно для верхнего и нижнего экрана.", "«Снимок» сохраняет верхний, нижний или оба экрана.")),
            "nl" to Entry("Helderheid, geluid en schermafbeeldingen", "Bediening per scherm op het dashboard.", listOf("Helderheid stel je per scherm apart in.", "Geluid kan apart voor het bovenste en onderste scherm worden ingesteld.", "Capture slaat het bovenste, onderste of beide schermen op.")),
            "es" to Entry("Brillo, sonido y capturas", "Controles por pantalla en el panel.", listOf("El brillo se ajusta por separado en cada pantalla.", "El sonido puede ajustarse aparte para la pantalla superior e inferior.", "Captura guarda la pantalla superior, la inferior o ambas.")),
            "de" to Entry("Helligkeit, Ton und Screenshots", "Steuerung pro Bildschirm im Dashboard.", listOf("Die Helligkeit wird für jeden Bildschirm separat eingestellt.", "Der Ton lässt sich für oberen und unteren Bildschirm getrennt einstellen.", "Aufnahme speichert den oberen, unteren oder beide Bildschirme.")),
            "fr" to Entry("Luminosité, son et captures", "Réglages par écran sur le tableau.", listOf("La luminosité se règle séparément pour chaque écran.", "Le son peut être réglé séparément pour l'écran du haut et du bas.", "Capture enregistre l'écran du haut, du bas ou les deux.")),
            "it" to Entry("Luminosità, audio e screenshot", "Controlli per schermo nel pannello.", listOf("La luminosità si regola separatamente per ogni schermo.", "L'audio può essere regolato separatamente per schermo superiore e inferiore.", "Acquisisci salva lo schermo superiore, inferiore o entrambi.")),
            "zh" to Entry("亮度、声音与截图", "仪表盘上的分屏控制。", listOf("每个屏幕可单独调节亮度。", "上屏和下屏可分别设置音量。", "截图可保存上屏、下屏或双屏。"))
        )),
        Topic("memory", "ram", mapOf(
            "en" to Entry("Swap & zRAM", "Extra virtual memory on storage.", listOf("Settings → Virtual memory adds a swap file of 1–16 GB; it is re-enabled after every boot.", "Large files take a few minutes to prepare on F2FS — PocketHub shows the progress.", "Swap is slower than RAM and does not add physical memory. The memory card shows only the swap file; zRAM (compressed RAM) is separate.")),
            "ru" to Entry("Swap и zRAM", "Дополнительная виртуальная память на накопителе.", listOf("Настройки → Виртуальная память добавляет swap-файл на 1–16 ГБ; он включается снова после каждой загрузки.", "Большой файл на F2FS готовится несколько минут — PocketHub показывает ход подготовки.", "Swap медленнее ОЗУ и не добавляет физическую память. Карточка памяти показывает только swap-файл; zRAM (сжатая ОЗУ) считается отдельно.")),
            "nl" to Entry("Swap en zRAM", "Extra virtueel geheugen op opslag.", listOf("Instellingen → Virtueel geheugen voegt een swapbestand van 1–16 GB toe; het wordt na elke start opnieuw ingeschakeld.", "Grote bestanden hebben op F2FS enkele minuten nodig — PocketHub toont de voortgang.", "Swap is trager dan RAM en voegt geen fysiek geheugen toe. De kaart toont alleen het swapbestand; zRAM staat los.")),
            "es" to Entry("Swap y zRAM", "Memoria virtual extra en el almacenamiento.", listOf("Ajustes → Memoria virtual añade un archivo swap de 1–16 GB; se reactiva tras cada arranque.", "Los archivos grandes tardan unos minutos en prepararse en F2FS; PocketHub muestra el progreso.", "El swap es más lento que la RAM y no añade memoria física. La tarjeta solo muestra el archivo swap; zRAM va aparte.")),
            "de" to Entry("Swap und zRAM", "Zusätzlicher virtueller Speicher auf dem Laufwerk.", listOf("Einstellungen → Virtueller Speicher fügt eine Swap-Datei von 1–16 GB hinzu; sie wird nach jedem Start wieder aktiviert.", "Große Dateien brauchen auf F2FS einige Minuten — PocketHub zeigt den Fortschritt.", "Swap ist langsamer als RAM und erhöht den physischen Speicher nicht. Die Karte zeigt nur die Swap-Datei; zRAM ist getrennt.")),
            "fr" to Entry("Swap et zRAM", "Mémoire virtuelle supplémentaire sur le stockage.", listOf("Réglages → Mémoire virtuelle ajoute un fichier swap de 1 à 16 Go ; il est réactivé à chaque démarrage.", "Les gros fichiers prennent quelques minutes sur F2FS — PocketHub affiche la progression.", "Le swap est plus lent que la RAM et n'ajoute pas de mémoire physique. La carte n'affiche que le fichier swap ; zRAM est à part.")),
            "it" to Entry("Swap e zRAM", "Memoria virtuale aggiuntiva nell'archiviazione.", listOf("Impostazioni → Memoria virtuale aggiunge un file swap da 1–16 GB; viene riattivato a ogni avvio.", "I file grandi richiedono alcuni minuti su F2FS — PocketHub mostra l'avanzamento.", "Lo swap è più lento della RAM e non aggiunge memoria fisica. La scheda mostra solo il file swap; zRAM è separata.")),
            "zh" to Entry("Swap 与 zRAM", "在存储上增加虚拟内存。", listOf("设置 → 虚拟内存 可添加 1–16 GB 的 swap 文件，每次开机后会自动重新启用。", "在 F2FS 上准备大文件需要几分钟，PocketHub 会显示进度。", "Swap 比内存慢，不会增加物理内存。内存卡片只显示 swap 文件；zRAM（压缩内存）另行计算。"))
        )),
        Topic("themes", "dark", mapOf(
            "en" to Entry("Themes & appearance", "Change the whole look, not just colours.", listOf("Settings → Interface design: Aurora Live (default, animated), Pop Gradient, Glass, Compact, Neon, Arcade, Solstice, Synthwave, Volcanic, 8-Bit, Neo-Brutal light and dark.", "Colour accent appears only for Glass, Compact, Neon and Arcade; the other designs bring their own palette.", "Aurora Live and Pop Gradient use animated icons; only the active profile, a spinning fan and active tiles move.", "Touchpad and PC keyboard follow the Aurora and Neo-Brutal themes. Keyboard themes are chosen separately in Settings → Keyboard.")),
            "ru" to Entry("Темы и оформление", "Меняют весь вид, а не только цвета.", listOf("Настройки → Дизайн интерфейса: Живая аврора (по умолчанию, анимированная), Поп-градиент, Стекло, Компактный, Неон, Аркада, Солнцестояние, Синтвейв, Вулкан, 8-бит, Необрутализм светлый и тёмный.", "Цветовая схема доступна только для Стекла, Компактного, Неона и Аркады; остальные темы со своей палитрой.", "«Живая аврора» и «Поп-градиент» используют анимированные иконки; двигаются только активный профиль, вращающийся вентилятор и включённые плитки.", "Тачпад и PC-клавиатура подстраиваются под Аврору и Необрутализм. Темы клавиатуры выбираются отдельно в Настройки → Клавиатура.")),
            "nl" to Entry("Thema's en uiterlijk", "Verander de hele stijl, niet alleen kleuren.", listOf("Instellingen → Interface-ontwerp: Levend noorderlicht (standaard, geanimeerd), Pop-verloop, Glas, Compact, Neon, Arcade, Zonnewende, Synthwave, Vulkanisch, 8-bit, Neo-brutaal licht en donker.", "Kleuraccent verschijnt alleen bij Glas, Compact, Neon en Arcade; de andere ontwerpen hebben een eigen palet.", "Levend noorderlicht en Pop-verloop gebruiken geanimeerde iconen; alleen het actieve profiel, een draaiende ventilator en actieve tegels bewegen.", "Touchpad en pc-toetsenbord volgen Aurora en Neo-brutaal. Toetsenbordthema's kies je apart in Instellingen → Toetsenbord.")),
            "es" to Entry("Temas y apariencia", "Cambian todo el aspecto, no solo los colores.", listOf("Ajustes → Diseño de interfaz: Aurora viva (por defecto, animada), Pop degradado, Cristal, Compacto, Neón, Arcade, Solsticio, Neón retro, Volcánico, 8-bit, Neobrutalista claro y oscuro.", "El color de acento solo aparece en Cristal, Compacto, Neón y Arcade; los demás diseños tienen su propia paleta.", "Aurora viva y Pop degradado usan iconos animados; solo se mueven el perfil activo, el ventilador girando y los accesos activos.", "El panel táctil y el teclado de PC siguen Aurora y Neobrutalista. Los temas del teclado se eligen en Ajustes → Teclado.")),
            "de" to Entry("Designs und Aussehen", "Ändern den ganzen Look, nicht nur Farben.", listOf("Einstellungen → Interface-Design: Aurora Live (Standard, animiert), Pop Gradient, Glas, Kompakt, Neon, Arcade, Sonnenwende, Synthwave, Vulkan, 8-Bit, Neo-Brutal hell und dunkel.", "Die Akzentfarbe erscheint nur bei Glas, Kompakt, Neon und Arcade; die übrigen Designs bringen eigene Farben mit.", "Aurora Live und Pop Gradient nutzen animierte Symbole; nur aktives Profil, drehender Lüfter und aktive Kacheln bewegen sich.", "Touchpad und PC-Tastatur folgen Aurora und Neo-Brutal. Tastatur-Designs wählst du separat unter Einstellungen → Tastatur.")),
            "fr" to Entry("Thèmes et apparence", "Changent tout le style, pas seulement les couleurs.", listOf("Réglages → Design de l'interface : Aurora vivante (par défaut, animée), Pop dégradé, Verre, Compact, Néon, Arcade, Solstice, Synthwave, Volcanique, 8-bit, Néo-brutal clair et sombre.", "La couleur d'accent n'apparaît que pour Verre, Compact, Néon et Arcade ; les autres designs ont leur propre palette.", "Aurora vivante et Pop dégradé utilisent des icônes animées ; seuls le profil actif, le ventilateur qui tourne et les tuiles actives bougent.", "Le pavé tactile et le clavier PC suivent Aurora et Néo-brutal. Les thèmes du clavier se choisissent dans Réglages → Clavier.")),
            "it" to Entry("Temi e aspetto", "Cambiano tutto lo stile, non solo i colori.", listOf("Impostazioni → Design interfaccia: Aurora viva (predefinito, animato), Pop sfumato, Vetro, Compatto, Neon, Arcade, Solstizio, Synthwave, Vulcanico, 8-bit, Neo-brutale chiaro e scuro.", "Il colore d'accento compare solo per Vetro, Compatto, Neon e Arcade; gli altri design hanno una propria palette.", "Aurora viva e Pop sfumato usano icone animate; si muovono solo il profilo attivo, la ventola in rotazione e le schede attive.", "Touchpad e tastiera PC seguono Aurora e Neo-brutale. I temi della tastiera si scelgono in Impostazioni → Tastiera.")),
            "zh" to Entry("主题与外观", "改变整体风格，而不仅是颜色。", listOf("设置 → 界面设计：极光（默认，动态）、流行渐变、玻璃、紧凑、霓虹、街机、夏至、合成波、火山、8 位、新粗野主义浅色与深色。", "强调色仅适用于玻璃、紧凑、霓虹和街机；其他设计自带配色。", "“极光”和“流行渐变”使用动态图标；只有当前配置、转动的风扇和开启的图块会动。", "触控板和电脑键盘会跟随极光和新粗野主义主题。键盘主题在 设置 → 键盘 中单独选择。"))
        )),
        Topic("settings", "cpu", mapOf(
            "en" to Entry("Settings, AYANEO button & startup", "System integration and permissions.", listOf("Start PocketHub after boot: the last profile, fan mode, overheat protection and swap come back automatically.", "AYANEO button takeover: PocketHub enables its Accessibility service and switches off the conflicting AYANEO ones on first start and after every boot.", "AYANEO Home and AYASpace switches turn those components on or off.", "Most system controls need root; the badge on the dashboard shows the root status. All changes to system values are restored by a reboot.")),
            "ru" to Entry("Настройки, кнопка AYANEO и автозапуск", "Интеграция с системой и разрешения.", listOf("Запуск PocketHub после загрузки: последний профиль, режим вентилятора, защита от перегрева и swap возвращаются автоматически.", "Перехват кнопки AYANEO: при первом запуске и после каждой загрузки PocketHub включает свою службу Accessibility и отключает конфликтующие службы AYANEO.", "Переключатели AYANEO Home и AYASpace включают или выключают эти компоненты.", "Большинству системных функций нужен root; значок на главной показывает его статус. Все изменения системных значений сбрасываются перезагрузкой.")),
            "nl" to Entry("Instellingen, AYANEO-knop en opstarten", "Systeemintegratie en rechten.", listOf("PocketHub starten na opstarten: laatste profiel, ventilatormodus, oververhittingsbeveiliging en swap komen automatisch terug.", "AYANEO-knopovername: bij de eerste start en na elke herstart zet PocketHub zijn toegankelijkheidsdienst aan en de conflicterende AYANEO-diensten uit.", "Schakelaars voor AYANEO Home en AYASpace zetten die onderdelen aan of uit.", "De meeste systeembediening vereist root; de badge op het dashboard toont de status. Een herstart zet systeemwaarden terug.")),
            "es" to Entry("Ajustes, botón AYANEO e inicio", "Integración con el sistema y permisos.", listOf("Iniciar PocketHub al arrancar: el último perfil, el modo del ventilador, la protección térmica y el swap vuelven solos.", "Asignación del botón AYANEO: al primer inicio y tras cada arranque, PocketHub activa su servicio de accesibilidad y desactiva los de AYANEO que interfieren.", "Los interruptores AYANEO Home y AYASpace activan o desactivan esos componentes.", "La mayoría de controles del sistema requieren root; la insignia del panel muestra su estado. Reiniciar restaura los valores del sistema.")),
            "de" to Entry("Einstellungen, AYANEO-Taste und Autostart", "Systemintegration und Berechtigungen.", listOf("PocketHub nach dem Booten starten: letztes Profil, Lüftermodus, Überhitzungsschutz und Swap kommen automatisch zurück.", "AYANEO-Tastenübernahme: beim ersten Start und nach jedem Booten aktiviert PocketHub seinen Bedienungshilfen-Dienst und schaltet störende AYANEO-Dienste ab.", "Schalter für AYANEO Home und AYASpace aktivieren oder deaktivieren diese Komponenten.", "Die meisten Systemfunktionen brauchen Root; das Abzeichen im Dashboard zeigt den Status. Ein Neustart setzt Systemwerte zurück.")),
            "fr" to Entry("Réglages, bouton AYANEO et démarrage", "Intégration système et autorisations.", listOf("Lancer PocketHub au démarrage : dernier profil, mode du ventilateur, protection thermique et swap reviennent automatiquement.", "Reprise du bouton AYANEO : au premier lancement et à chaque démarrage, PocketHub active son service d'accessibilité et coupe ceux d'AYANEO en conflit.", "Les interrupteurs AYANEO Home et AYASpace activent ou désactivent ces composants.", "La plupart des commandes système nécessitent root ; le badge du tableau indique l'état. Un redémarrage rétablit les valeurs système.")),
